-- Run once in the Supabase SQL editor (safe to rerun).
-- Upload PDFs as Vorsorgevollmacht.pdf and Patientenverfuegung.pdf to the public bucket documents.
create table if not exists public.kis_cards (
  id text primary key, patient_id text not null, documents jsonb not null,
  facts jsonb not null default '[]', care_preferences jsonb not null default '[]',
  updated_at timestamptz not null default now()
);
alter table public.kis_cards enable row level security;
drop policy if exists kis_cards_select on public.kis_cards;
create policy kis_cards_select on public.kis_cards for select to anon, authenticated using (true);
grant select on public.kis_cards to anon, authenticated;

create table if not exists public.kis_card_scans (
  id bigint generated always as identity primary key,
  card_id text not null check (char_length(card_id) between 1 and 64),
  created_at timestamptz not null default now()
);
alter table public.kis_card_scans enable row level security;
drop policy if exists kis_card_scans_insert on public.kis_card_scans;
create policy kis_card_scans_insert on public.kis_card_scans for insert to anon, authenticated with check (true);
drop policy if exists kis_card_scans_select on public.kis_card_scans;
create policy kis_card_scans_select on public.kis_card_scans for select to anon, authenticated using (true);
grant select, insert on public.kis_card_scans to anon, authenticated;
grant usage on sequence public.kis_card_scans_id_seq to anon, authenticated;
do $$
begin
  if exists(select 1 from pg_publication where pubname='supabase_realtime') then
    if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='kis_card_scans') then
      alter publication supabase_realtime add table public.kis_card_scans;
    end if;
  end if;
end $$;

insert into public.kis_cards (id, patient_id, documents, facts, care_preferences)
values ('demo', '26004179', '[{"id":"26004179-vorsorge","title":"Vorsorgevollmacht (BMJ-Formular)","kind":"Vorsorgevollmacht","date":"12.06.2025","received":"05.11.2026 09:40","status":"Dokumentiert","pages":[{"heading":"Personen","sections":[]},{"heading":"Gesundheitssorge und Aufenthalt","sections":[]},{"heading":"Behörden und Vermögenssorge","sections":[]},{"heading":"Weitere Befugnisse und Unterschrift","sections":[]}],"provenance":{"kind":"original-form","label":"BMJ-Formular Vorsorgevollmacht","url":"/pdfs/Vorsorgevollmacht.pdf","version":"Januar 2023","note":"Originalformular mit synthetisch ausgefüllten Feldern (Henri Becker / Martin Becker). Ohne Unterschrift; keine rechtswirksame Vollmacht."},"file":"Vorsorgevollmacht.pdf"},{"id":"26004179-patientenverfuegung","title":"Patientenverfügung (Formular Bayern)","kind":"Patientenverfügung","date":"18.08.2025","received":"05.11.2026 09:40","status":"Dokumentiert","pages":[{"heading":"Situationen und Behandlungswünsche","sections":[]},{"heading":"Ablehnungen und Hinweise","sections":[]},{"heading":"Vertrauenspersonen","sections":[]},{"heading":"Widerruf und Unterschrift","sections":[]}],"provenance":{"kind":"original-form","label":"Formular Patientenverfügung, Bayerisches Staatsministerium der Justiz","url":"https://www.justiz.bayern.de/Vorsorge","version":"22. Auflage","note":"Originalformular mit synthetisch ausgefüllten Feldern. Ohne Unterschrift; keine rechtswirksame Verfügung."},"file":"Patientenverfuegung.pdf"}]'::jsonb, '[{"id":"vertretung","label":"Gesundheitsvertretung","value":"Martin Becker","condition":"Vollmacht wirkt nur, solange Martin Becker die Vollmachtsurkunde besitzt und im Original vorlegen kann.","exclusions":["Ärztliche Zwangsmaßnahmen und die Verbringung zu deren Durchführung sind im Formular mit „nein“ angekreuzt.","Vermögenssorge und Wohnungsauflösung sind nicht erteilt."],"person":"Martin Becker","documentId":"26004179-vorsorge","page":2,"section":"1. Gesundheitssorge/Pflegebedürftigkeit","quote":"Sie darf in allen Angelegenheiten der Gesundheitssorge entscheiden, ebenso über alle Einzelheiten einer ambulanten oder (teil-)stationären Pflege.","category":"representation"},{"id":"wille","label":"Behandlungswünsche","value":"Lindernde Behandlung","condition":"Nur im unmittelbaren Sterbeprozess oder im Endstadium einer unheilbaren, tödlich verlaufenden Krankheit (Nr. 1 angekreuzt).","exclusions":["Gehirnschädigung und fortgeschrittene Demenz sind nicht angekreuzt; künstliche Ernährung ist nicht abgelehnt."],"person":"","documentId":"26004179-patientenverfuegung","page":1,"section":"2. In allen unter Nummer 1 beschriebenen und angekreuzten Situationen verlange ich","quote":"Lindernde pflegerische Maßnahmen, insbesondere Mundpflege zur Vermeidung des Durstgefühls, sowie lindernde ärztliche Maßnahmen, im Speziellen Medikamente zur wirksamen Bekämpfung von Schmerzen, Luftnot, Angst, Unruhe, Erbrechen und anderen Krankheitserscheinungen.","category":"wishes"},{"id":"betreuung","label":"Betreuungswunsch","value":"Martin Becker","condition":"Erst relevant, falls trotz Vollmacht eine rechtliche Betreuung erforderlich wird.","exclusions":["Keine gerichtliche Bestellung dokumentiert."],"person":"Martin Becker","documentId":"26004179-vorsorge","page":4,"section":"8. Betreuungsverfügung","quote":"Falls trotz dieser Vollmacht eine gesetzliche Vertretung („rechtliche Betreuung“) erforderlich sein sollte, bitte ich, die oben bezeichnete Vertrauensperson als Betreuer zu bestellen.","category":"care"},{"id":"auskunft","label":"Auskunftsrecht","value":"Martin Becker","condition":"Behandelnde Ärzte und Pflegepersonal sind gegenüber Martin Becker von der Schweigepflicht entbunden.","exclusions":["Vermögensangelegenheiten sind nicht umfasst."],"person":"Martin Becker","documentId":"26004179-vorsorge","page":2,"section":"1. Gesundheitssorge/Pflegebedürftigkeit","quote":"Sie darf Krankenunterlagen einsehen und deren Herausgabe an Dritte bewilligen.","category":"information"}]'::jsonb, '[{"id":"schmerz","label":"Schmerz- und Symptombehandlung","value":"Linderung, auch bei möglicher Lebenszeitverkürzung","condition":"Nur im unmittelbaren Sterbeprozess oder im Endstadium einer unheilbaren, tödlich verlaufenden Krankheit (Nr. 1 angekreuzt).","exclusions":["Gilt nur in den angekreuzten Situationen; keine allgemeine Therapieanordnung."],"person":"","documentId":"26004179-patientenverfuegung","page":1,"section":"2. In allen unter Nummer 1 beschriebenen und angekreuzten Situationen verlange ich","quote":"Die Möglichkeit einer Verkürzung meiner Lebenszeit durch diese Maßnahmen nehme ich in Kauf.","category":"wishes","target":"Schmerztherapie"},{"id":"reanimation","label":"Wiederbelebung","value":"In den angekreuzten Situationen abgelehnt","condition":"Nur im unmittelbaren Sterbeprozess oder im Endstadium einer unheilbaren, tödlich verlaufenden Krankheit (Nr. 1 angekreuzt).","exclusions":["Keine pauschale DNR-Anordnung; andere Notfallsituationen sind damit nicht geregelt."],"person":"","documentId":"26004179-patientenverfuegung","page":2,"section":"3. In den unter Nummer 1 beschriebenen und angekreuzten Situationen lehne ich Folgendes ab","quote":"Wiederbelebungsmaßnahmen.","category":"wishes","target":"Notfallplanung"},{"id":"beatmung","label":"Lebensverlängernde Maßnahmen","value":"In den angekreuzten Situationen abgelehnt","condition":"Nur im unmittelbaren Sterbeprozess oder im Endstadium einer unheilbaren, tödlich verlaufenden Krankheit (Nr. 1 angekreuzt).","exclusions":["Gilt nur in den angekreuzten Situationen."],"person":"","documentId":"26004179-patientenverfuegung","page":2,"section":"3. In den unter Nummer 1 beschriebenen und angekreuzten Situationen lehne ich Folgendes ab","quote":"Maßnahmen, die zum Zweck der Lebenserhaltung bzw. Lebensverlängerung eingesetzt werden und nicht ausschließlich der Linderung von Leiden dienen, wie z. B. maschinelle Beatmung, Dialyse oder Operationen.","category":"wishes","target":"Beatmung"}]'::jsonb)
on conflict (id) do update set patient_id = excluded.patient_id, documents = excluded.documents,
  facts = excluded.facts, care_preferences = excluded.care_preferences, updated_at = now();
